head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil51200";
scwin.loadTp = 'null';
scwin.result = null;
scwin.attachFiles_2 = null;
scwin.attachFiles_3 = null;
scwin.attachFiles_3_2 = null;
scwin.attachFiles_2_2 = null;
scwin.attachFiles_2_3 = null;
scwin.attachFiles_3_3 = null;
scwin.apiUrl = undefined;
scwin.urlInfo = null;
scwin.apiFileCheck = null;
scwin.apiFileDownload = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — apiYn, listProcsStatCd, uploadCode, isOk

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(((String(dma_basicComInfo.get("listTpClssCd")) === "02") ? "상장법인" : "심사진행법인")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb2", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_basicComInfo.get("mktTpNm")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_basicComInfo.get("secugrpNm")); } },
        { childId: "ipt_fileItmNm_3", attr: "toolTip", fn: function () { return String(dlt_attachList.getCellData(60100, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r1", attr: "toolTip", fn: function () { return String(dlt_attachList.getCellData(60200, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r2", attr: "toolTip", fn: function () { return String(dlt_attachList.getCellData(60300, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r3", attr: "toolTip", fn: function () { return String(dlt_attachList.getCellData(60400, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r4", attr: "toolTip", fn: function () { return String(dlt_attachList.getCellData(60500, "attach_file_itm_nm")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_apiYn", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "if_requiredYn_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "docuItem_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "if_apiYn_2", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "tr_130", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "docuItem_3", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "if_apiYn_3", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "tr_149", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "docuItem_4", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "if_listProcsStatCd", grids: ["grd_formFileList"], fn: function(){ return ((dma_pageContext.get("listProcsStatCd") ?? "") === ''); } }, { id: "if_useYn_2", fn: function(){ return ((dlt_attachList.getCellData(0, "useYn") ?? (() => { throw new Error("unresolved:" + "ent.useYn"); })())==='Y'); } }, { id: "if_fileSeq_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "fileSeq") ?? (() => { throw new Error("unresolved:" + "entity.fileSeq"); })()) === (dlt_attachList.getCellData(0, "attachFileSeq") ?? (() => { throw new Error("unresolved:" + "ent.attachFileSeq"); })())); } }, { id: "docuItem_2_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "fileSeq") ?? (() => { throw new Error("unresolved:" + "entity.fileSeq"); })()) === (dlt_attachList.getCellData(0, "attachFileSeq") ?? (() => { throw new Error("unresolved:" + "ent.attachFileSeq"); })())); } }, { id: "if_requiredYn_4", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "docuItem_2_2", fn: function(){ return ((dlt_formFileList.getCellData(0, "requiredYn") ?? (() => { throw new Error("unresolved:" + "entity.requiredYn"); })()) === 'N'); } }, { id: "if_apiYn_4", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "tr_248", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "docuItem_2_3", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") === 'Y'); } }, { id: "if_apiYn_5", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "tr_270", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "docuItem_3_2", fn: function(){ return ((dma_pageContext.get("apiYn") ?? "") !== 'Y'); } }, { id: "if_listProcsStatCd_2", grids: ["grd_formFileList_3"], fn: function(){ return ((dma_pageContext.get("listProcsStatCd") ?? "") !== ''); } }, { id: "btn_doSave", fn: function(){ return ((dma_pageContext.get("listProcsStatCd") ?? "") === '' || (dma_pageContext.get("listProcsStatCd") ?? "") === '30' || (dma_pageContext.get("listProcsStatCd") ?? "") === '35' || (dma_pageContext.get("listProcsStatCd") ?? "") === '37'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_110", entity: "dlt_formFileList", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return String(i + 1) + "."; } }, { childId: "ipt_fileItmNm_2", fn: function (v, i) { return String(v("fileItmNm")); } }] },
        { genId: "c_foreach_225", entity: "dlt_attachList", countIds: [], cells: [{ childId: "__rc12", fn: function (v, i) { return String(i + 1) + "."; } }, { childId: "ipt_remk_6", fn: function (v, i) { return String(v("remk")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } },
        { childId: "ipt_fileItmNm_3", fn: function () { return String(dlt_attachList.getCellData(60100, "attach_file_itm_nm")); } },
        { childId: "__rb6", fn: function () { return String(dlt_attachList.getCellData(60100, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r1", fn: function () { return String(dlt_attachList.getCellData(60200, "attach_file_itm_nm")); } },
        { childId: "__rb7", fn: function () { return String(dlt_attachList.getCellData(60200, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r2", fn: function () { return String(dlt_attachList.getCellData(60300, "attach_file_itm_nm")); } },
        { childId: "__rb8", fn: function () { return String(dlt_attachList.getCellData(60300, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r3", fn: function () { return String(dlt_attachList.getCellData(60400, "attach_file_itm_nm")); } },
        { childId: "__rb9", fn: function () { return String(dlt_attachList.getCellData(60400, "attach_file_itm_nm")); } },
        { childId: "ipt_fileItmNm_3_r4", fn: function () { return String(dlt_attachList.getCellData(60500, "attach_file_itm_nm")); } },
        { childId: "__rb10", fn: function () { return String(dlt_attachList.getCellData(60500, "attach_file_itm_nm")); } },
        { childId: "ipt_bzProcsNo_2", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        form = (document.preListForm || { elements: [] });
        scwin.setEditMode(null);
        await scwin.checkSave();
        $(':file').change(async function() {
                const id = $(this).attr('id');
                const vfile = $('#' + id)[0].files[0];
                const val = $('#' + id)[0].value;
                if (vfile != null) {
                    if (vfile.size === 0) {
                        await $c.win.alert('0byte파일은 첨부할 수 없습니다.');
                        $(this).val("");
                    }
                    const chkFileSize = vfile.size;
                    let mSize = 20;
                    if (id.indexOf("Api") > -1) {
                        mSize = 100;
                    }
                    if (chkFileSize > mSize * (1024 * 1024)) {
                        await $c.win.alert('첨부파일의 용량은 개당 ' + mSize + 'MB를 넘을 수 없습니다.');
                        $(this).val("");
                    }
                    const fVal = val.split("\\");
                    const fNm = fVal[fVal.length - 1];
                    if (scwin.calBytes(fNm) > 80) {
                        await $c.win.alert('파일명이 너무 길면 첨부할 수 없습니다.');
                        $(this).val("");
                    }
                    const isFileType = ["bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt"];
                    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
                    let typeChkCnt = 0;
                    for (i = 0; i < isFileType.length; i++) {
                        if (isFileType[i] === fileType) {
                            typeChkCnt++;
                        }
                    }
                    if (typeChkCnt === 0) {
                        await $c.win.alert('첨부할 수 없는 확장자입니다.\n사용가능 확장자 : bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
                        $(this).val("");
                    }
                }
        });

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil51200.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51200' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.apiUrl =urlInfo(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.attachFiles_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_2"]');
        scwin.attachFiles_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_3"]');
        scwin.attachFiles_3_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_3_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_3_2"]');
        scwin.attachFiles_2_2 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_2_2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_2_2"]');
        scwin.attachFiles_2_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_2_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_2_3"]');
        scwin.attachFiles_3_3 = (typeof __krxFileControl === 'function') ? __krxFileControl('attachFiles_3_3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="attachFiles_3_3"]');
        scwin.urlInfo = urlInfo;
        scwin.apiFileCheck = apiFileCheck;
        scwin.apiFileDownload = apiFileDownload;
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_PrelistPageSearch_onclick
 * @description 「목록보기」 클릭 이벤트
