/**
 * @method
 * @name grd_formFileList_3_oncellclick
 * @description grd_formFileList_3 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formFileList_3_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formFileList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_formFileList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.editAttach("this"); return;
        scwin.isNotRelated("this"); return;
        if (String(r["useYn"]) === "Y") { await scwin.downloadFile(r["attachFileSeq"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList_3.oncellclick' });
    }
};

