function urlInfo() {
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
}

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

async function apiFileCheck() {
    const oData = await scwin.getOtherData();
    if (oData === '' || oData == null || oData === 'undefined') {
        void('fn_apiFileCheck() apiKey 조회에 실패');
        return false;
    } else {
        const arr = oData.split('||');
        const apiUrl = urlInfo();
        const editObj2 = document.getElementsByName('editYnApi');
        const chkObj2 = document.getElementsByName('useYnApi');
        const itmObj2 = document.getElementsByName('fileItmNmApi');
        const remkObj2 = document.getElementsByName('remkApi');
        const fileSeq2 = document.getElementsByName('fileSeqApi');
        let fileObj2;
        let useYnFlag;
        let fileObjVal;
        let fileNmVal;
        for (let i = 0; i < chkObj2.length; i++) {
            if ((scwin.loadTp !== 2 && scwin.loadTp !== 3 && !chkObj2[i].disabled) || ((scwin.loadTp === 2 || scwin.loadTp === 3) && editObj2[i].checked)) {
                fileObj2 = form['attachFilesApi['+i+']'];
                if (chkObj2[i].checked) {
                    useYnFlag = "N";
                    fileObjVal = "";
                    fileNmVal = "";
                } else {
                    useYnFlag = "Y";
                    fileObjVal = fileObj2.files[0];
                    fileNmVal = itmObj2[i].value;
                }
                const formData = new FormData();
                formData.append("attachFile", fileObjVal);
                formData.append("integUsrId", arr[1]);
                formData.append("attachFileItmNm", fileNmVal);
                formData.append("useYn", useYnFlag);
                formData.append("remk", remkObj2[i].value);
                if (!scwin.apiFileUpload(arr[0], fileSeq2[i].value, formData)) {
                    await $c.win.alert("저장이 실패하였습니다. 관리자에게 문의하세요.");
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * @method
 * @name apiFileUpload
 * @description api File Upload 처리
 * @param {*} apiKey apiKey
 * @param {*} attach_file_seq attach_file_seq
 * @param {*} formData formData
 * @returns {void}
 * @hidden N
 */
scwin.apiFileUpload = function (apiKey, attach_file_seq, formData) {
    let errCnt = 0;
    const bzProcsNo = $c.util.getComponent('dma_pageContext').get('bzProcsNo');
    const fileTpCd = form.fileTpCd.value;
    const dtlTpCd = form.dtlTpCd.value;
    const seq = attach_file_seq;
    $.ajax({ url: scwin.apiUrl + "/auth/s1/list-invstg/list-invstg-attach/file-upload/" + bzProcsNo + "/" + fileTpCd + "/" + dtlTpCd + "/" + seq, type: "POST", data: formData, processData: false, contentType: false, async: false, headers: { "apiKey": apiKey }, success: function(response) {
                void('success : ' + response);
            }, error: function(request, status, error) {
                void('request : ' + request);
                void('status : ' + status);
                void('error : ' + error);
                errCnt++;
            } });
    if (errCnt === 0) {
        return true;
    } else {
        return false;
    }
};

async function apiFileDownload(attach_file_seq) {
    const bzProcsNo = $c.util.getComponent('dma_pageContext').get('bzProcsNo');
    const fileTpCd = form.fileTpCd.value;
    const dtlTpCd = form.dtlTpCd.value;
    const seq = attach_file_seq;
    const oData = await scwin.getOtherData();
    if (oData === '' || oData == null || oData === 'undefined') {
        void('fn_apiFileDownload() apiKey 조회에 실패');
        return;
    } else {
        const arr = oData.split('||');
        const apiUrl = urlInfo();
        (document.apiDownloadForm || { elements: [] }).action = apiUrl + "/auth/s1/list-invstg/list-invstg-attach/file-download/" + bzProcsNo + "/" + fileTpCd + "/" + dtlTpCd + "/" + seq;
        $c.util.getComponent("dma_downloadFileReq").set("apiKey", arr[0]);
        $c.util.getComponent("dma_downloadFileReq").set("integUsrId", arr[1]);
        const p = {}; p["apiKey"] = $c.util.getComponent("ipt_apiKey").getValue(); p["integUsrId"] = $c.util.getComponent("ipt_integUsrId").getValue(); $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil51200/jldfil51200.xml', p);
    }
}

